prelude:
set -eu
g() { git -c user.name=Fixture -c user.email=fixture@example.invalid -c commit.gpgsign=false -c core.hooksPath=/dev/null "$@"; }
commit_all() { g -C "$REPO" add -A; g -C "$REPO" commit -qm "$1"; }

stand_in_pm:
#!/bin/sh
case "$1" in
  install)
    n=$(cat "$PM_DIR/install.n" 2>/dev/null || echo 0)
    n=$((n + 1))
    echo "$n" > "$PM_DIR/install.n"
    if [ -f "$PM_DIR/install.sh" ]; then . "$PM_DIR/install.sh"; fi
    exit "$(cat "$PM_DIR/install.status" 2>/dev/null || echo 0)" ;;
  *) printf 'stand-in %s\n' "$*" ;;
esac

stand_in_gh:
#!/bin/sh
case "$1 $2" in
  "api advisories"*) ;;
  *) echo "gh stand-in: unexpected call: $*" >&2; exit 99 ;;
esac
if [ -f "$GH_DIR/fail" ]; then
  cat "$GH_DIR/fail" >&2
  exit 1
fi
cat "$GH_DIR/advisories.json"
